const input = $json.body ?? $json;
const required = ['invoice_id', 'invoice_number', 'customer', 'services', 'final_amount', 'payment_status', 'invoice_datetime'];
const missing = required.filter((key) => input[key] === undefined || input[key] === null || input[key] === '');
if (missing.length || input.payment_status !== 'CONFIRMED' || !input.customer?.email || !Array.isArray(input.services) || !input.services.length) {
  throw new Error(`Invalid invoice payload: ${missing.join(', ') || 'email, services, or payment status'}`);
}
const escape = (value) => String(value ?? '').replace(/[&<>\"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const money = (value) => `₹${Number(value || 0).toFixed(2)}`;
const rows = input.services.map((service) => `<tr><td>${escape(service.name)}</td><td>${service.quantity || 1}</td><td>${money(service.price)}</td><td>${money(Number(service.price || 0) * Number(service.quantity || 1))}</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;color:#292524;margin:36px}h1{color:#9f5f61;margin-bottom:4px}.muted{color:#78716c}.meta{display:flex;justify-content:space-between;margin:28px 0}.box{background:#fff7f7;border:1px solid #ead3d4;padding:16px;border-radius:8px}table{width:100%;border-collapse:collapse;margin-top:24px}th{background:#9f5f61;color:white;text-align:left}th,td{padding:11px;border-bottom:1px solid #e7e5e4}.totals{margin-left:auto;width:280px;margin-top:22px}.totals div{display:flex;justify-content:space-between;padding:5px}.grand{font-size:18px;font-weight:bold;border-top:2px solid #292524;margin-top:8px;padding-top:10px}</style></head><body><h1>${escape(input.salon?.name || 'Salon Management System')}</h1><div class="muted">${escape(input.salon?.address)}<br>${escape(input.salon?.phone)} | ${escape(input.salon?.email)}</div><div class="meta"><div class="box"><b>Billed to</b><br>${escape(input.customer.name)}<br>${escape(input.customer.email)}<br>${escape(input.customer.phone)}</div><div><b>Invoice:</b> ${escape(input.invoice_number)}<br><b>Date:</b> ${escape(input.invoice_datetime)}<br><b>Payment:</b> ${escape(input.payment_method)}<br><b>Status:</b> PAID</div></div><table><thead><tr><th>Service</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table><div class="totals"><div><span>Subtotal</span><span>${money(input.subtotal)}</span></div><div><span>Discount</span><span>- ${money(input.discount)}</span></div><div><span>Tax/GST</span><span>${money(input.tax)}</span></div><div class="grand"><span>Final Amount</span><span>${money(input.final_amount)}</span></div></div><p class="muted">Thank you for visiting us.</p></body></html>`;
return [{ json: { ...input, receipt_html: html } }];

const result = $json;
const failed = Boolean(result.error || result.statusCode >= 400);
return [{ json: { invoice_id: $('Validate and Build Receipt HTML').item.json.invoice_id, status: failed ? 'FAILED' : 'SENT', error: failed ? String(result.error?.message || result.message || 'Email delivery failed') : '', execution_id: $execution.id } }];
